DamageStyleList.Formula:
// Define Constants
const user = this.subject();
const target = arguments[0];
const item = this.item();
const a = this.subject();
const b = target;
const v = $gameVariables._data;
const sign = [3, 4].includes(item.damage.type) ? -1 : 1;

// Create Power
const power = Math.max(eval(item.damage.formula), 0);

// Declare Values
let value = 0;
let level = Math.max(a.level || a.luk, 1);
let armor = this.isPhysical() ? b.def : b.mdf;
armor = Math.max(this.applyArmorModifiers(target, armor), 0);
let attackStat = 0;
if (this.isPhysical() && (this.isDamage() || this.isDrain())) {
    attackStat = a.atk;
} else if (this.isMagical() && (this.isDamage() || this.isDrain())) {
    attackStat =  a.mat;
} else if (this.isPhysical() && this.isRecover()) {
    attackStat =  a.def;
} else if (this.isMagical() && this.isRecover()) {
    attackStat =  a.mdf;
}

// Calculate Damage
value = (((((2 * level) / 5) + 2) * power * (attackStat / armor)) / 50) + 2;

// Return Value
return (isNaN(value) ? 0 : value) * sign;

