default.OverallFormulaJS:
// Declare Constants
const target = arguments[0];
const critical = arguments[1];
const item = this.item();

// Get Base Damage
const baseValue = this.evalDamageFormula(target);

// Calculate Element Modifiers
let value = baseValue * this.calcElementRate(target);

// Calculate Physical and Magical Modifiers
if (this.isPhysical()) {
    value *= target.pdr;
}
if (this.isMagical()) {
    value *= target.mdr;
}

// Apply Healing Modifiers
if (baseValue < 0) {
    value *= target.rec;
}

// Apply Critical Modifiers
if (critical) {
    value = this.applyCritical(value);
}

// Apply Variance and Guard Modifiers
value = this.applyVariance(value, item.damage.variance);
value = this.applyGuard(value, target);

// Finalize Damage
value = Math.round(value);
return value;

default.VarianceFormulaJS:
// Declare Constants
const damage = arguments[0];
const variance = arguments[1];

// Calculate Variance
const amp = Math.floor(Math.max((Math.abs(damage) * variance) / 100, 0));
const v = Math.randomInt(amp + 1) + Math.randomInt(amp + 1) - amp;

// Return Damage
return damage >= 0 ? damage + v : damage - v;

default.GuardFormulaJS:
// Declare Constants
const damage = arguments[0];
const target = arguments[1];

// Return Damage Early
const note = this.item().note;
if (note.match(/<UNBLOCKABLE>/i)) return damage;
if (!target.isGuard()) return damage;
if (damage < 0) return damage;

// Declare Guard Rate
let guardRate = 0.5;
guardRate /= target.grd;

// Return Damage
return damage * guardRate;

default.CriticalHitRateJS:
// Declare Constants
const user = this.subject();
const target = arguments[0];

// Create Base Critical Rate
let rate = this.subject().cri * (1 - target.cev);

// Apply Notetags
const note = this.item().note;
if (note.match(/<ALWAYS CRITICAL>/i)) {
    return 1;
}
if (note.match(/<SET CRITICAL RATE:[ ](\d+)([%％])>/i)) {
    return Number(RegExp.$1) / 100;
}
if (note.match(/<MODIFY CRITICAL RATE:[ ](\d+)([%％])>/i)) {
    rate *= Number(RegExp.$1) / 100;
}
if (note.match(/<MODIFY CRITICAL RATE:[ ]([\+\-]\d+)([%％])>/i)) {
    rate += Number(RegExp.$1) / 100;
}
if (note.match(/<JS CRITICAL RATE>\s*([\s\S]*)\s*<\/JS CRITICAL RATE>/i)) {
    const code = String(RegExp.$1);
    try {
        eval(code);
    } catch (e) {
        if ($gameTemp.isPlaytest()) console.log(e);
    }
}

// Apply LUK Buffs/Debuffs
const lukStack = this.subject().buff(7);
rate *= 2 ** lukStack;

// Return Rate
return rate;

default.CriticalHitMultiplier:
// Declare Constants
const user = this.subject();
let damage = arguments[0];
let multiplier = 2.0;
let bonusDamage = this.subject().luk * this.subject().cri;
if (this.isHpRecover() || this.isMpRecover()) {
    bonusDamage *= -1;
}

// Apply Notetags
const note = this.item().note;
if (note.match(/<MODIFY CRITICAL MULTIPLIER:[ ](\d+)([%％])>/i)) {
    multiplier = Number(RegExp.$1) / 100;
}
if (note.match(/<MODIFY CRITICAL MULTIPLIER:[ ]([\+\-]\d+)([%％])>/i)) {
    multiplier += Number(RegExp.$1) / 100;
}
if (note.match(/<MODIFY CRITICAL BONUS DAMAGE:[ ](\d+)([%％])>/i)) {
    bonusDamage *= Number(RegExp.$1) / 100;
}
if (note.match(/<MODIFY CRITICAL BONUS DAMAGE:[ ]([\+\-]\d+)([%％])>/i)) {
    bonusDamage += bonusDamage * (RegExp.$1) / 100;
}
if (note.match(/<JS CRITICAL DAMAGE>\s*([\s\S]*)\s*<\/JS CRITICAL DAMAGE>/i)) {
    const code = String(RegExp.$1);
    try {
        eval(code);
    } catch (e) {
        if ($gameTemp.isPlaytest()) console.log(e);
    }
}

// Return Damage
return damage * multiplier + bonusDamage;

