// Declare Coordinates
let x = 0;
let y = 0;

// Hit Text
const hitText = this.hitText();
const hitTextSize = this.textSizeEx(hitText);
if (this.textAlignment() === 'right') {
    x = this.innerWidth - this.itemPadding() - hitTextSize.width;
} else if (this.textAlignment() === 'center') {
    x = Math.floor((this.innerWidth - hitTextSize.width) / 2);
} else {
    x = this.itemPadding();
}
this.drawTextEx(hitText, x, y);

// New Line
y += Math.ceil(this.lineHeight() * 2/3);

// Damage Text
const dmgText = this.damageText();
const dmgTextSize = this.textSizeEx(dmgText);
if (this.textAlignment() === 'right') {
    x = this.innerWidth - this.itemPadding() - dmgTextSize.width;
} else if (this.textAlignment() === 'center') {
    x = Math.floor((this.innerWidth - dmgTextSize.width) / 2);
} else {
    x = this.itemPadding();
}
this.drawTextEx(dmgText, x, y);

